const E = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const n = value => Number.isFinite(Number(value)) ? Number(value) : 0;
const fmt = value => n(value) >= 10000 ? `${(n(value)/10000).toFixed(1)}万` : Math.floor(n(value)).toLocaleString('zh-CN');
const ACTIONS = {rest:'调息休憩',heal:'疗养伤势',cultivate:'静心修炼',wood:'采集灵木',stone:'开采青石',herb:'采集灵草',food:'采集山蔬',teach:'公开讲法',study:'研习传承',walk:'行走',travel:'山外游历',work:'照料院务',eat:'用膳',social:'与人交谈',quest:'个人历练',forage:'采寻野食',breakthrough:'调息突破'};
const TABS = [['self','掌门','person'],['build','营造','build'],['disciples','门人','people'],['manuals','传承','book'],['production','生产','leaf'],['sect','山门','mountain'],['explore','山外','compass'],['journal','纪事','scroll']];
const PATHS = {jade:'m12 2 7 6-3 13H8L5 8l7-6Zm-7 6h14M8 21l4-13 4 13',wood:'m4 17 12-12 5 5L9 22l-5-5ZM6 15l5 5M9 12l5 5',stone:'m3 10 8-6 10 5-3 11H7L3 10Zm0 0 10 3 8-4m-8 4 5 7',food:'M3 10h18l-4 10H7L3 10Zm4-3 2-4m3 4V2m4 5-1-4',crystal:'m12 2 7 8-3 12H8L5 10l7-8Zm-7 8h14m-7-8v20',person:'M12 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8ZM5 21v-3a7 7 0 0 1 14 0v3',build:'m4 20 9-9m-3-5 3-3 8 8-3 3-8-8ZM3 17l4 4',people:'M9 3a3 3 0 1 1 0 6 3 3 0 0 1 0-6ZM3 20v-4a6 6 0 0 1 12 0v4m2-15a3 3 0 0 1 0 6m1 3a5 5 0 0 1 3 5v1',book:'M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2V4Z',leaf:'M5 20c0-9 6-15 15-16 0 10-4 16-12 16H5Zm0 0 10-10',mountain:'m2 20 8-15 6 11 3-6 4 10H2ZM8 9l2 2 2-2',compass:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Zm-4 14 2-6 6-2-2 6-6 2Z',scroll:'M6 3h13v16H7a3 3 0 0 1 0-6h12M6 3a3 3 0 0 0 0 6h1V3M10 7h6m-6 3h6',close:'m6 6 12 12M6 18 18 6',chevron:'m7 10 5 5 5-5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',settings:'M9 4h6l1 4 4 2v4l-4 2-1 4H9l-1-4-4-2v-4l4-2 1-4Zm3 5a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',pin:'M12 21c-5-6-8-9-8-13a8 8 0 0 1 16 0c0 4-3 7-8 13Zm0-16a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',grid:'M3 3h18v18H3V3Zm6 0v18m6-18v18M3 9h18M3 15h18',check:'m4 12 5 5L20 6',more:'M4 12h1m6 0h1m6 0h1',arrow:'M4 12h16m-6-6 6 6-6 6'};
const icon = (name, cls='') => `<svg class="ea-icon ${cls}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${PATHS[name] || PATHS.mountain}"/></svg>`;
const dataArgs = args => E(JSON.stringify(args));
const btn = (label, action, args=[], options={}) => `<button type="button" class="${options.className || 'secondary'}${options.full?' full':''}" data-ui-action="${E(action)}" data-ui-args="${dataArgs(args)}"${options.lock ? ` disabled title="${E(options.lock)}"` : ''}${options.pressed!==undefined?` aria-pressed="${options.pressed}"`:''}>${options.icon?icon(options.icon):''}${E(label)}</button>`;
const note = (text, kind='') => text ? `<p class="ui-note ${kind}">${E(text)}</p>` : '';
const empty = (title,text,glyph='缘') => `<div class="ea-empty"><span class="empty-seal" aria-hidden="true">${glyph}</span><h3>${E(title)}</h3><p>${E(text)}</p></div>`;
const bar = (value, max=100, cls='') => `<div class="ea-progress ${cls}" role="progressbar" aria-valuemin="0" aria-valuemax="${n(max)}" aria-valuenow="${Math.round(n(value))}"><span style="width:${Math.max(0,Math.min(100,n(value)/Math.max(1,n(max))*100))}%"></span></div>`;
const meter = (label,value,max=100,cls='') => `<div class="meter-row"><span>${E(label)}</span><b>${fmt(value)}<small> / ${fmt(max)}</small></b></div>${bar(value,max,cls)}`;
const list = value => Array.isArray(value) ? value : [];

// SR-XF-016/029: HUD is a read-only projection of the same location as the scene.
export function scenePresentation(s, viewScene='map') {
  const stage=SIM.stage(s)||0, local=s.master.location, travel=s.srWorld&&s.travelsById?.[s.srWorld.activeTravelId];
  const old=SIM.explorationOptions(s)?.active;
  const baseWeather=SIM.worldSummary(s)?.weather||s.world?.weather;
  const fallbackWeather=typeof baseWeather==='string'?baseWeather:baseWeather?.name||baseWeather?.label||'晴';
  if(viewScene==='journey'&&old)return {title:old.regionName,subtitle:s.combat?.status==='active'?'临敌战场':old.status==='traveling'?'山路途中':'亲往调查',weather:SIM.WEATHER?.[s.world.exploration?.weather]?.name||fallbackWeather};
  if(travel&&local?.kind!=='local')return {title:'前往'+(SIM.WORLD_SCENES?.[travel.destination]?.name||'已知地点'),subtitle:travel.routeName||'山路途中',weather:'行旅途中',travel:true};
  const at=s.srWorld&&local?.kind==='local'?SIM.WORLD_SCENES?.[local.sceneId]:null;
  if(at){const home=at.id==='scene:yunxiu-courtyard',knownWeather=s.weatherByRegionId?.['region:yunxiu']?.phase;return {title:home&&s.sect?.name&&stage>=3?s.sect.name:at.name,subtitle:home?'云岫山 · '+(SIM.STAGE_NAMES?.[stage]||'山院初成'):'掌门所在 · '+at.name,weather:home||['valley','market','quarry','ruins','prison','supply','ward','qixia'].includes(at.regionId)?({clear:'晴',rain:'雨',fog:'雾',wind:'风'}[knownWeather]||fallbackWeather):'此地天时尚未查明',sceneId:at.id};}
  return {title:viewScene==='valley'?'青萝山谷':viewScene==='lake'?'寒潭遗境':stage>=3?s.sect?.name||'云岫别院':'云岫别院',subtitle:'云岫山 · '+(SIM.STAGE_NAMES?.[stage]||'山院初成'),weather:fallbackWeather};
}
export function currentObjective(s){
  const next=nextObjective(s);
  if(s.srWorld&&s.master.realm>=10&&next.label==='准备筑基')return {label:'查看已知道路',text:'筑基已成。可继续经营与研习，或沿已知线索亲赴山外。',kind:'explore'};
  return next;
}

